// class key → [family, talent profile]
export const TOP_MULTIKILL_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","base"],"Journeyman":["beginner","base"],"Maestro":["beginner","base"],"Voidwalker":["beginner","t46"],"Warrior":["warrior","base"],"Barbarian":["warrior","base"],"Blood_Berserker":["warrior","base"],"Death_Bringer":["warrior","base"],"Squire":["warrior","base"],"Divine_Knight":["warrior","base"],"Archer":["archer","base"],"Bowman":["archer","base"],"Siege_Breaker":["archer","base"],"Hunter":["archer","base"],"Beast_Master":["archer","base"],"Wind_Walker":["archer","base"],"Mage":["mage","base"],"Shaman":["mage","base"],"Bubonic_Conjuror":["mage","base"],"Arcane_Cultist":["mage","base"],"Wizard":["mage","t469"],"Elemental_Sorcerer":["mage","t469"],"Royal_Guardian":["warrior","base"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_MULTIKILL_DEFAULT_FAMILY = "archer";

/** The top Multikill reference for a class — its family's base merged with its profile. */
export function topMultikillFlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_MULTIKILL_CLASS_PROFILE[classKey]) || [TOP_MULTIKILL_DEFAULT_FAMILY, "base"];
  const base = TOP_MULTIKILL_FAMILY_FLAT[family] ?? TOP_MULTIKILL_FAMILY_FLAT[TOP_MULTIKILL_DEFAULT_FAMILY];
  const override = TOP_MULTIKILL_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
